  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Temp&#233;r&#233;-(Paladin).html&quot; title=&quot;Champion temp&#233;r&#233;&quot;&gt;Champion temp&#233;r&#233;&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Les paladins gris ont d&#233;couvert que dans un monde d&#39;intrigues, un code d&#39;honneur strict r&#233;duit leurs options. Leur divergence par rapport au code normal des paladins les affaiblit toujours, mais d&#39;une mani&#232;re ou d&#39;une autre, ils ont trouv&#233; un moyen d&#39;&#233;viter de perdre tous leurs pouvoirs.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Alignement&lt;a class=&quot;headeranchor&quot; id=&quot;Alignement_0&quot; href=&quot;#Alignement_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un paladin gris peut &#234;tre Loyal Bon, Loyal Neutre ou Neutre Bon, mais il doit toujours v&#233;n&#233;rer une divinit&#233; Loyale Bonne, Neutre Bonne ou Loyale Neutre. Cela modifie les restrictions d&#39;alignement du paladin.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_1&quot; href=&quot;#Comp&#233;tences_de_classe_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un paladin gris ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe. Cela modifie les comp&#233;tences de classe du paladin.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Gr&#226;ce affaiblie&lt;a class=&quot;headeranchor&quot; id=&quot;Gr&#226;ce_affaiblie_2&quot; href=&quot;#Gr&#226;ce_affaiblie_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le code assoupli d&#39;un paladin gris affaiblit son lien avec le pouvoir qui lui conf&#232;re ses capacit&#233;s de paladin. Il gagne sa premi&#232;re utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du Mal&lt;/a&gt; au niveau 2, au lieu du niveau 1, mais gagne tout de m&#234;me d&#39;autres utilisations de ch&#226;timent du Mal &#224; la fr&#233;quence indiqu&#233;e dans la table “&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#TABLEPALADIN&quot; title=&quot;Le paladin&quot;&gt;Le Paladin&lt;/a&gt;”. Il ne gagne jamais les capacit&#233;s de classe &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADUBIEN&quot; title=&quot;Le paladin&quot;&gt;aura du Bien&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACEDIVINE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce divine&lt;/a&gt;. Son &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADECOURAGE&quot; title=&quot;Le paladin&quot;&gt;aura de courage&lt;/a&gt; ne l&#39;immunise pas contre la terreur, son &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEFERMETE&quot; title=&quot;Le paladin&quot;&gt;aura de fermet&#233;&lt;/a&gt; ne l&#39;immunise pas contre les charmes et son &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEDROITURE&quot; title=&quot;Le paladin&quot;&gt;aura de droiture&lt;/a&gt; ne l&#39;immunise pas contre les coercition. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du Mal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADECOURAGE&quot; title=&quot;Le paladin&quot;&gt;aura de courage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEFERMETE&quot; title=&quot;Le paladin&quot;&gt;aura de fermet&#233;&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEDROITURE&quot; title=&quot;Le paladin&quot;&gt;aura de droiture&lt;/a&gt;, et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADUBIEN&quot; title=&quot;Le paladin&quot;&gt;aura du Bien&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#GRACEDIVINE&quot; title=&quot;Le paladin&quot;&gt;gr&#226;ce divine&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Code de conduite&lt;a class=&quot;headeranchor&quot; id=&quot;Code_de_conduite_3&quot; href=&quot;#Code_de_conduite_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un paladin gris doit &#234;tre d&#39;alignement Loyal Bon, Loyal Neutre ou Neutre Bon et perd toutes ses capacit&#233;s de classe, &#224; l&#39;exception des comp&#233;tences, si jamais il commet volontairement un acte mal&#233;fique (par exemple, en lan&#231;ant un sort avec le &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;registre&lt;/a&gt; du Mal). Il doit s&#39;efforcer d&#39;agir avec honneur et de respecter les principes de sa foi, mais ne pas le faire ne constitue pas une violation de son code, et en dehors des actions mal&#233;fiques, il peut faire tout ce qu&#39;il juge n&#233;cessaire pour d&#233;fendre les causes de la loi et du bien. Cette capacit&#233; remplace le code de conduite du paladin et les capacit&#233;s associ&#233;es, et modifie la section &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#ANCIENPALADIN&quot; title=&quot;Le paladin&quot;&gt;anciens paladins&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sant&#233; renforc&#233;e (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Sant&#233;_renforc&#233;e_Ext_4&quot; href=&quot;#Sant&#233;_renforc&#233;e_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, un paladin gris est bien moins &#233;tranger aux poisons qu&#39;un paladin normal. Il gagne un bonus de saintet&#233; de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;Les maladies&quot;&gt;maladies&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#SANTEDIVINE&quot; title=&quot;Le paladin&quot;&gt;sant&#233; divine&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ch&#226;timent cibl&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Ch&#226;timent_cibl&#233;_Sur_5&quot; href=&quot;#Ch&#226;timent_cibl&#233;_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, un paladin gris peut d&#233;penser deux utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du Mal&lt;/a&gt; afin de ch&#226;tier une cr&#233;ature non-Bonne qui n&#39;est pas mal&#233;fique et d&#39;en tirer tous les avantages habituels. Le paladin gris doit v&#233;ritablement croire que la cr&#233;ature qu&#39;il ch&#226;tie est un adversaire de la cause du bien. M&#234;me si cet ennemi non-Mauvais est un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;mort-vivant&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;dragon&lt;/a&gt;, il n&#39;ajoute pas de d&#233;g&#226;ts suppl&#233;mentaires &#224; sa premi&#232;re attaque r&#233;ussie. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CANALISATIONDENERGIEPOSITIVE&quot; title=&quot;Le paladin&quot;&gt;canalisation d&#39;&#233;nergie positive&lt;/a&gt; et modifie &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du Mal&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Aura de subtilit&#233; (Mag, Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_subtilit&#233;_Mag_Sur_6&quot; href=&quot;#Aura_de_subtilit&#233;_Mag_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, un paladin gris apprend &#224; se prot&#233;ger de la d&#233;tection. Lui et ses alli&#233;s &#224; moins de 3 m&#232;tres gagnent un bonus de moral de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Divination.html&quot; title=&quot;Divination&quot;&gt;divination&lt;/a&gt;. De plus, les lanceurs de divinations qui ciblent le paladin gris ou ses alli&#233;s proches doivent r&#233;ussir un test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; comme si le paladin gris et ses alli&#233;s proches &#233;taient sous l&#39;effet d&#39;un sort d’&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antid&#233;tection.html&quot; title=&quot;Antid&#233;tection&quot;&gt;antid&#233;tection&lt;/a&gt;&lt;/i&gt; lanc&#233; par le paladin gris, avec un niveau de lanceur de sorts &#233;gal au niveau de paladin du paladin gris.&lt;br /&gt;&lt;br /&gt;Cette capacit&#233; fonctionne tant que le paladin gris est conscient ou qu&#39;il dort, mais pas s&#39;il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; pour toute autre raison, ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Mort.html&quot; title=&quot;Mort&quot;&gt;mort&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#AURADEJUSTICE&quot; title=&quot;Le paladin&quot;&gt;aura de justice&lt;/a&gt;.
